def get_entry(key: str):
    try:
        return ENTRIES[key]
    except KeyError:
        raise ValueError(f"unknown Priority-B exact asset key: {key}")


def png_to_4bpp(path: Path, expected_size: int) -> bytes:
    with Image.open(path) as img:
        if img.mode != "P":
            raise ValueError(f"{path}: indexed PNG required, got {img.mode}")
        w, h = img.size
        if w % 8 or h % 8:
            raise ValueError(f"{path}: dimensions must be multiples of 8")
        px = list(img.getdata())
    if px and max(px) > 15:
        raise ValueError(f"{path}: palette index > 15 in 4bpp image")
    out = bytearray()
    for ty in range(0, h, 8):
        for tx in range(0, w, 8):
            for y in range(8):
                row = (ty + y) * w + tx
                for x in range(0, 8, 2):
                    out.append(px[row + x] | (px[row + x + 1] << 4))
    if len(out) < expected_size:
        raise ValueError(f"{path}: not enough tile data")
    if any(out[expected_size:]):
        raise ValueError(f"{path}: padding tiles after canonical data must remain zero")
    return bytes(out[:expected_size])


def inc_to_raw(path: Path) -> bytes:
    out = bytearray()
    for lineno, source in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        line = source.split("@", 1)[0].strip()
        if not line:
            continue
        m = re.fullmatch(r"\.(byte|2byte|4byte)\s+(.+)", line)
        if not m:
            raise ValueError(f"{path}:{lineno}: only .byte/.2byte/.4byte supported")
        width = {"byte": 1, "2byte": 2, "4byte": 4}[m.group(1)]
        for token in m.group(2).split(","):
            value = int(token.strip(), 0)
            if not 0 <= value < (1 << (width * 8)):
                raise ValueError(f"{path}:{lineno}: value out of range: {token}")
            out.extend(value.to_bytes(width, "little"))
    return bytes(out)


def repack(key: str, raw: bytes, output: Path) -> None:
    entry = get_entry(key)
    expected = int(entry["raw_size"])
    if len(raw) != expected:
        raise ValueError(f"{key}: raw size 0x{len(raw):X} != 0x{expected:X}")
    encoded = repack_raw_with_plan(raw, entry["plan"])
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_bytes(encoded)


def cmd_png(args) -> None:
    entry = get_entry(args.key)
    raw = png_to_4bpp(Path(args.input), int(entry["raw_size"]))
    repack(args.key, raw, Path(args.output))


def cmd_inc(args) -> None:
    repack(args.key, inc_to_raw(Path(args.input)), Path(args.output))


def cmd_palette(args) -> None:
    path = Path(args.input)
    with Image.open(path) as img:
        if img.mode != "P":
            raise ValueError(f"{path}: indexed PNG required for palette extraction")
        pal = img.getpalette()
    if pal is None or len(pal) < 48:
        raise ValueError(f"{path}: fewer than 16 palette entries")
    raw = bytearray()
    for i in range(16):
        r, g, b = pal[i * 3:i * 3 + 3]
        value = (r >> 3) | ((g >> 3) << 5) | ((b >> 3) << 10)
        raw.extend(value.to_bytes(2, "little"))
    out = Path(args.output)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(raw)


def main() -> int:
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="command", required=True)
    p = sub.add_parser("repack-png")
    p.add_argument("--key", required=True)
    p.add_argument("input"); p.add_argument("output")
    p.set_defaults(func=cmd_png)
    p = sub.add_parser("repack-inc")
    p.add_argument("--key", required=True)
    p.add_argument("input"); p.add_argument("output")
    p.set_defaults(func=cmd_inc)
    p = sub.add_parser("encode-indexed-palette")
    p.add_argument("input"); p.add_argument("output")
    p.set_defaults(func=cmd_palette)
    args = ap.parse_args()
    try:
        args.func(args)
    except (OSError, ValueError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
